  const tavernActiveContentSource = tavernActiveContentExists
    ? fs.readFileSync(tavernActiveContentPath, "utf8")
    : "";

  assert.equal(tavernActiveContentExists, true);
  assert.match(tavernSource, /from "\.\/tavern-active-content"/);
